/* 真机全屏会横向裁切房间背景。粉色窝垫实际中心约在房间高度 45%，
   睡眠槽位必须全部留在窝内；多只动物使用独立槽位，不能互相覆盖。 */
const PET_SLEEP_LAYOUTS={
  1:[{x:20.5,y:45.0}],
  2:[{x:15.7,y:45.0},{x:25.3,y:45.0}],
  3:[{x:14.8,y:46.4},{x:20.5,y:42.3},{x:26.2,y:46.4}],
  4:[{x:15.1,y:42.7},{x:25.9,y:42.7},{x:15.1,y:47.1},{x:25.9,y:47.1}],
};
function petSleepSpot(index,total){const count=Math.max(1,Math.min(4,total||1)),layout=PET_SLEEP_LAYOUTS[count]||PET_SLEEP_LAYOUTS[1];return layout[Math.max(0,index)%layout.length];}
