function petClamp(v,a,b){return Math.max(a,Math.min(b,+v||0));}
function petSpeciesKey(species){return Object.prototype.hasOwnProperty.call(PET_BREEDS,species)?species:'cat';}
function petSpeciesName(species){return {cat:'猫猫',dog:'狗狗',hamster:'仓鼠',rabbit:'兔子'}[petSpeciesKey(species)];}
function petSpeciesSound(species){return {cat:'喵～',dog:'汪！',hamster:'吱吱～',rabbit:'噗噗～'}[petSpeciesKey(species)];}
function petSpeciesIcon(species){return {cat:'⌁',dog:'◡',hamster:'●',rabbit:'♢'}[petSpeciesKey(species)];}
function petUid(){return typeof uid==='function'?uid():'pet_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);}
function petLatestMealAt(p){let latest=0;Object.values(p&&p.meals||{}).forEach(day=>{Object.values(day||{}).forEach(t=>{latest=Math.max(latest,+t||0);});});return latest;}
// Neglect may lower health and cause illness, but it must never reverse the
// pet's visible growth. Only the explicit milk-stage action may make it small.
function petThinFactor(){return 1;}
function petRoot(){
  S.me=S.me||{};
  if(!S.me.ePet||typeof S.me.ePet!=='object'||Array.isArray(S.me.ePet))S.me.ePet={coins:320,pets:[],activeId:'',inventory:{kibble:3,chicken:1,fish:1,snack:2,medicine:0},ownedWear:[],sharedRoleId:'',logs:[],version:2};
  const x=S.me.ePet;
  x.pets=Array.isArray(x.pets)?x.pets:[];
  x.inventory=x.inventory&&typeof x.inventory==='object'?x.inventory:{kibble:3,chicken:1,fish:1,snack:2,medicine:0};
  x.inventory.medicine=Math.max(0,Math.floor(+x.inventory.medicine||0));x.version=2;
  x.ownedWear=Array.isArray(x.ownedWear)?x.ownedWear:[];
  x.logs=Array.isArray(x.logs)?x.logs:[];
  x.coins=Math.max(0,Math.floor(+x.coins||0));
  if(!x.activeId&&x.pets[0])x.activeId=x.pets[0].id;
  x.pets.forEach(petNormalize);
  x.pets.forEach((p,i)=>{for(let j=0;j<i;j++){const q=x.pets[j];if(Math.hypot(p.roomX-q.roomX,p.roomY-q.roomY)<15){const spot=PET_ROOM_SPOTS[i%PET_ROOM_SPOTS.length];p.roomX=spot.x;p.roomY=spot.y;break;}}});
  petUpdateAll(x);
  return x;
}
function petNormalize(p){
  if(!p||typeof p!=='object')return;
  p.id=p.id||petUid();p.species=petSpeciesKey(p.species);p.name=String(p.name||'小团子').slice(0,12);
  p.bornAt=+p.bornAt||Date.now();p.lastUpdate=+p.lastUpdate||Date.now();p.lastPoopAt=+p.lastPoopAt||p.bornAt;
  ['hunger','clean','joy','energy','health','affection'].forEach(k=>p[k]=petClamp(p[k]==null?86:p[k],0,100));
  p.poop=petClamp(p.poop,0,6);p.careScore=petClamp(p.careScore==null?65:p.careScore,0,100);p.careActions=Math.max(0,+p.careActions||0);
  p.meals=p.meals&&typeof p.meals==='object'?p.meals:{};p.accessories=p.accessories&&typeof p.accessories==='object'?p.accessories:{head:'',neck:'',body:''};
  p.colors=p.colors&&typeof p.colors==='object'?p.colors:{fur:PET_BREEDS[p.species][0].fur,accent:'#ef8faa',cloth:'#db8ba8'};
  const breeds=PET_BREEDS[p.species],fallback=breeds[0].id;
  if(!breeds.some(b=>b.id===p.breed))p.breed=fallback;
  const compact=p.species==='hamster'||p.species==='rabbit',roomMinX=compact?11:p.species==='cat'?15:14,roomMaxX=compact?89:p.species==='cat'?84:86;
  p.roomX=petClamp(p.roomX==null?50:p.roomX,roomMinX,roomMaxX);p.roomY=petClamp(p.roomY==null?72:p.roomY,22,86);
  p.plumpness=petClamp(p.plumpness==null?0:p.plumpness,0,100);
  p.sleepPose=Math.max(0,Math.min(2,Math.floor(+p.sleepPose||0)));
  if(p.stageOverride!==0)delete p.stageOverride;
  p.strokes=Array.isArray(p.strokes)?p.strokes:[];p.looks=Array.isArray(p.looks)?p.looks:[];p.revealed=!!p.revealed;
  p.lastFedAt=+p.lastFedAt||petLatestMealAt(p)||Date.now();p.sick=!!p.sick;p.neglectThin=!!p.neglectThin;
}
function petBreed(species,id){const list=PET_BREEDS[petSpeciesKey(species)];return list.find(b=>b.id===id)||list[0];}
function petDefault(species,name,breed){
  const now=Date.now();
  species=petSpeciesKey(species);const b=petBreed(species,breed);
  return {id:petUid(),species,breed:b.id,name:String(name||'小团子').slice(0,12),bornAt:now,lastUpdate:now,lastPoopAt:now,lastFedAt:now,hunger:88,clean:92,joy:86,energy:88,health:100,affection:50,poop:0,careScore:68,careActions:0,meals:{},accessories:{head:'',neck:'',body:''},colors:{fur:b.fur,accent:'#ef8faa',cloth:'#db8ba8'},roomX:50,roomY:72,sleepPose:Math.floor(Math.random()*3),strokes:[],looks:[],revealed:false,mateId:'',speech:'',sick:false,neglectThin:false};
}
function petActive(){const x=petRoot();return x.pets.find(p=>p.id===x.activeId)||x.pets[0]||null;}
function petLocalDay(ts){const d=new Date(ts||Date.now());return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function petMealSlot(now){const h=new Date(now||Date.now()).getHours();return h>=5&&h<11?'breakfast':h>=11&&h<17?'lunch':h>=17?'dinner':'late';}
function petMealName(slot){return {breakfast:'早餐',lunch:'午餐',dinner:'晚餐',late:'夜宵'}[slot]||'加餐';}
function petIsNight(){const h=new Date().getHours();return h>=22||h<6;}
function petUpdateAll(x){
  const now=Date.now();let changed=false;
  (x.pets||[]).forEach(p=>{
    const elapsed=Math.min(96,Math.max(0,(now-(+p.lastUpdate||now))/PET_HOUR));
    if(elapsed>.02){
      p.hunger=petClamp(p.hunger-elapsed*3.15,0,100);
      p.clean=petClamp(p.clean-elapsed*(.75+p.poop*.24),0,100);
      p.joy=petClamp(p.joy-elapsed*(p.hunger<30?2.2:1.05),0,100);
      p.energy=petClamp(p.energy+(petIsNight()?elapsed*4.2:-elapsed*.65),0,100);
      if(p.hunger<20)p.plumpness=petClamp(p.plumpness-elapsed*.18,0,100);
      if(p.hunger<18||p.clean<16||p.joy<15)p.health=petClamp(p.health-elapsed*1.15,0,100);else if(p.hunger>55&&p.clean>55)p.health=petClamp(p.health+elapsed*.35,0,100);
      p.lastUpdate=now;changed=true;
    }
    const newPoop=Math.min(6,Math.floor((now-(+p.lastPoopAt||now))/(7*PET_HOUR)));
    if(newPoop>0){p.poop=petClamp(p.poop+newPoop,0,6);p.lastPoopAt+=(newPoop*7*PET_HOUR);changed=true;}
    const low=petMoodValue(p)<25;
    if(low&&!p.lowMoodSince){p.lowMoodSince=now;changed=true;}else if(!low&&p.lowMoodSince){p.lowMoodSince=0;changed=true;}
    p.depressed=!!(p.lowMoodSince&&now-p.lowMoodSince>8*PET_HOUR);
    const unfed=now-(+p.lastFedAt||now);
    if(p.neglectThin){p.neglectThin=false;changed=true;}
    if(unfed>3*PET_DAY&&!p.sick){p.sick=true;p.health=Math.min(p.health,42);p.joy=Math.min(p.joy,34);x.logs.unshift({time:now,text:(p.name+'因为超过三天没有喂食而生病了，需要使用宠物恢复药。').slice(0,100)});if(x.logs.length>200)x.logs.length=200;changed=true;}
    if(p.sick&&p.health>42){p.health=42;changed=true;}
  });
  if(changed&&typeof save==='function')save();
}
function petAgeInfo(p){
  const days=Math.max(0,(Date.now()-p.bornAt)/PET_DAY),boost=1,months=Math.max(0,Math.floor(days/30));
  let stage=0;for(let i=PET_STAGE_MONTHS.length-1;i>=0;i--)if(months>=PET_STAGE_MONTHS[i]){stage=i;break;}
  const naturalStage=stage;
  p.highestNaturalStage=Math.max(0,Math.min(4,Math.max(+p.highestNaturalStage||0,naturalStage)));
  stage=p.stageOverride===0?0:p.highestNaturalStage;
  const age=months<1?'未满1个月':months<12?months+'个月':Math.floor(months/12)+'岁'+(months%12?months%12+'个月':'');
  return {days,months,stage,naturalStage:p.highestNaturalStage,age,boost};
}
function petMoodValue(p){return Math.round(p.joy*.42+p.health*.26+p.hunger*.18+p.clean*.14);}
function petMoodLabel(p){const v=petMoodValue(p);if(p.sick)return'生病了';if(p.depressed)return'闷闷不乐';if(v<25)return'快要蔫了';if(v<45)return'有点委屈';if(v<68)return'安安静静';if(v<86)return'很开心';return'兴奋得转圈';}
function petLog(text,coin){const x=petRoot();x.logs.unshift({time:Date.now(),text:String(text||'').slice(0,100)});if(x.logs.length>200)x.logs.length=200;if(coin)x.coins=Math.max(0,x.coins+coin);save();}
function petRole(){const x=petRoot();return x.sharedRoleId&&typeof getC==='function'?getC(x.sharedRoleId):null;}
function petRoleName(){const c=petRole();return c?(c.remark||c.name):'';}
function petTogether(action){const n=petRoleName();return n?('你和'+n+'一起'+action):('你'+action);}

function petStrokePaths(p){return (p.strokes||[]).map(s=>{const pts=(s.points||[]).map((q,i)=>(i?'L':'M')+petClamp(q[0],0,320).toFixed(1)+' '+petClamp(q[1],0,320).toFixed(1)).join(' ');return pts?`<path d="${pts}" fill="none" stroke="${esc(s.color||'#c46f8b')}" stroke-width="${petClamp(s.width||6,2,24)}" stroke-linecap="round" stroke-linejoin="round"/>`:'';}).join('');}
function petIsSleeping(p){return !!(p&&((p.forcedSleepUntil||0)>Date.now()||(petIsNight()&&!((p.awakeUntil||0)>Date.now()))));}
function petBreedName(p){return petBreed(p&&p.species,p&&p.breed).name;}
