  if(id==='bow')return `<g transform="translate(204 73) rotate(10)"><path d="M0 16Q-31-4-34 20T0 25Q31-4 34 20T0 25Z" fill="${accent}" stroke="#fff" stroke-width="4"/><circle cx="0" cy="21" r="9" fill="#f7b0c2"/></g>`;
